-- SWAS Triage Batch Update v3
-- Source: Kruidvat, ICI PARIS XL, medeco.com, level.co, controlid.com.br, adamsrite.com, remaining_assets (ASSA ABLOY)
-- Generated 2026-08-03
-- NOTE: Whatnot, REI, Mars, Lyst reports excluded - no finding IDs present in source text.
-- NOTE: ID 22834 excluded - conflicting definitions across two source docs (GraphQL introspection
--       on yaleconnecthub.com vs origin-IP-bypass on controlid.com.br). Verify manually which is correct.

BEGIN;

CREATE TEMP TABLE _triage_batch3 (
    finding_id  INTEGER PRIMARY KEY,
    new_status  TEXT NOT NULL,
    outcome     TEXT,
    reason      TEXT NOT NULL
);

ON CONFLICT (finding_id) DO NOTHING;

UPDATE findings f
SET status = t.new_status,
    likely_program_outcome = t.outcome,
    triage_reasoning = t.reason
FROM _triage_batch3 t
WHERE f.id = t.finding_id;

-- Sanity check before commit
SELECT new_status, outcome, count(*)
FROM _triage_batch3
GROUP BY new_status, outcome
ORDER BY 1,2;

COMMIT;
